const dialog=document.querySelector('#project-dialog');
function openProject(project){const data=cases[project.dataset.project];document.querySelector('#dialog-title').textContent=data.title;document.querySelector('#dialog-category').textContent=data.category;document.querySelector('#dialog-intro').textContent=data.intro;document.querySelector('#case-problem').textContent=data.problem;document.querySelector('#case-approach').textContent=data.approach;document.querySelector('.case-steps').replaceChildren(...data.steps.map(([title,text])=>{const item=document.createElement('div'),heading=document.createElement('b'),paragraph=document.createElement('p');heading.textContent=title;paragraph.textContent=text;item.append(heading,paragraph);return item;}));document.querySelector('#dialog-visual').replaceChildren(project.querySelector('.project-visual').cloneNode(true));dialog.showModal();dialog.scrollTop=0;}
projects.forEach(project=>project.addEventListener('click',()=>{if(project.dataset.dragged==='true'){project.dataset.dragged='false';return;}openProject(project);}));
document.querySelectorAll('.close-dialog').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});d.addEventListener('close',()=>document.body.style.overflow='');});

document.querySelectorAll('dialog').forEach(d=>new MutationObserver(()=>{if(d.open)document.body.style.overflow='hidden';}).observe(d,{attributes:true,attributeFilter:['open']}));
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});projects.forEach(p=>p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter);if(document.body.classList.contains('canvas-mode'))resetPositions();}));
const navLinks=[...document.querySelectorAll('.nav-item')];const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){navLinks.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}});},{rootMargin:'-15% 0px -55% 0px'});document.querySelectorAll('main>section').forEach(s=>observer.observe(s));
let zoom=1,zIndex=1;const board=document.querySelector('.projects'),switchButton=document.querySelector('#view-switch');
function resetPositions(){let index=0;const width=innerWidth<=600?285:350;const gap=30;const columns=Math.max(1,Math.floor((board.clientWidth-40)/(width+gap)));projects.forEach(p=>{if(p.hidden)return;p.style.left=(25+(index%columns)*(width+gap))+'px';p.style.top=(25+Math.floor(index/columns)*365)+'px';p.style.zIndex=1;index++;});}
function setZoom(value){zoom=Math.max(.6,Math.min(1.4,value));board.style.setProperty('--zoom',zoom);document.querySelector('#zoom-level').textContent=Math.round(zoom*100)+'%';}
function exitCanvas(){document.body.classList.remove('canvas-mode');switchButton.setAttribute('aria-pressed','false');switchButton.innerHTML='<span aria-hidden="true">▦</span> 项目画布';document.querySelector('.canvas-tools').hidden=true;projects.forEach(p=>{p.style.left='';p.style.top='';p.style.zIndex='';});}
switchButton.addEventListener('click',()=>{if(document.body.classList.contains('canvas-mode')){exitCanvas();document.querySelector('#work').scrollIntoView();return;}document.body.classList.add('canvas-mode');switchButton.setAttribute('aria-pressed','true');switchButton.innerHTML='<span aria-hidden="true">☷</span> 网页视图';document.querySelector('.canvas-tools').hidden=false;setZoom(1);resetPositions();window.scrollTo({top:0,behavior:'instant'});});
navLinks.forEach(a=>a.addEventListener('click',()=>{if(document.body.classList.contains('canvas-mode'))exitCanvas();}));
document.querySelector('#zoom-in').addEventListener('click',()=>setZoom(zoom+.1));document.querySelector('#zoom-out').addEventListener('click',()=>setZoom(zoom-.1));document.querySelector('#reset-canvas').addEventListener('click',()=>{setZoom(1);resetPositions();});
projects.forEach(p=>{let drag=null;p.addEventListener('pointerdown',e=>{if(!document.body.classList.contains('canvas-mode')||e.button!==0)return;p.dataset.dragged='false';drag={x:e.clientX,y:e.clientY,left:parseFloat(p.style.left)||0,top:parseFloat(p.style.top)||0};p.setPointerCapture(e.pointerId);p.style.zIndex=++zIndex;});p.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>6){p.dataset.dragged='true';p.classList.add('dragging');p.style.left=Math.max(0,drag.left+dx)+'px';p.style.top=Math.max(0,drag.top+dy)+'px';}});const end=()=>{drag=null;p.classList.remove('dragging');};p.addEventListener('pointerup',end);p.addEventListener('pointercancel',end);p.addEventListener('keydown',e=>{if(!document.body.classList.contains('canvas-mode')||!e.altKey||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const dx=e.key==='ArrowLeft'?-20:e.key==='ArrowRight'?20:0,dy=e.key==='ArrowUp'?-20:e.key==='ArrowDown'?20:0;p.style.left=Math.max(0,(parseFloat(p.style.left)||0)+dx)+'px';p.style.top=Math.max(0,(parseFloat(p.style.top)||0)+dy)+'px';});p.setAttribute('aria-description','点击查看详情；画布模式下可拖动，或按 Alt 加方向键移动。');});


